package auth

import (
	"crypto/rand"
	"crypto/subtle"
	"encoding/base32"
	"fmt"
	"strings"
	"time"

	"github.com/pocketbase/dbx"
	"github.com/pocketbase/pocketbase/core"
	"github.com/pquerna/otp"
	"github.com/pquerna/otp/hotp"
	"github.com/pquerna/otp/totp"

	"github.com/EatWell-Studio/OSFM/internal/store"
)

// TOTP (RFC 6238) as authenticator apps expect it: HMAC-SHA1, 30-second steps, 6 digits, a 160-bit secret (RFC 4226
// recommends at least 128 bits). The secret is generated by the server and stored encrypted ([sealTOTPSecret]).
//
// A code is accepted for the current time step and one step either side (±30 s), for clocks that are slightly off
// and for the time it takes to type the code. Each accepted step is recorded in credentials.totp_last_step with a
// conditional update that only moves it forward, so a code cannot be used twice, not even by two requests at the same
// moment, and neither can an older code once a newer one has been used.
const (
	totpPeriod     = 30
	totpDigits     = otp.DigitsSix
	totpSkew       = 1
	totpSecretSize = 20
)

var totpOpts = hotp.ValidateOpts{Digits: totpDigits, Algorithm: otp.AlgorithmSHA1}

// newTOTPSecret returns a new random TOTP secret.
func newTOTPSecret() ([]byte, error) {
	b := make([]byte, totpSecretSize)
	if _, err := rand.Read(b); err != nil {
		return nil, fmt.Errorf("auth: TOTP secret: %w", err)
	}
	return b, nil
}

// totpKey returns the otpauth:// key of secret for the authenticator app: issuer (the instance's name) and account
// (the login name) label the entry in the app. A colon would end the issuer part of the label early, so colons in the
// issuer become spaces (and runs of spaces one).
func totpKey(secret []byte, issuer, account string) (*otp.Key, error) {
	return totp.Generate(totp.GenerateOpts{
		Issuer:      strings.Join(strings.Fields(strings.ReplaceAll(issuer, ":", " ")), " "),
		AccountName: account,
		Period:      totpPeriod,
		Secret:      secret,
		Digits:      totpDigits,
		Algorithm:   otp.AlgorithmSHA1,
	})
}

// totpStep returns the RFC 6238 time step of t.
func totpStep(t time.Time) int64 {
	return t.Unix() / totpPeriod
}

// normalizeTOTPCode returns the code without spaces, and whether it has the form of a code at all.
func normalizeTOTPCode(code string) (string, bool) {
	code = strings.Join(strings.Fields(code), "")
	if len(code) != totpDigits.Length() {
		return "", false
	}
	for _, c := range code {
		if c < '0' || c > '9' {
			return "", false
		}
	}
	return code, true
}

// matchTOTP returns the newest time step within the allowed skew of t, and after the step after, for which code is
// the code of secret. Every candidate step is computed and compared in constant time, whether or not one matches.
func matchTOTP(secret []byte, code string, t time.Time, after int64) (step int64, ok bool) {
	code, wellFormed := normalizeTOTPCode(code)
	if !wellFormed {
		return 0, false
	}
	s := base32.StdEncoding.EncodeToString(secret)
	current := totpStep(t)
	for candidate := current - totpSkew; candidate <= current+totpSkew; candidate++ {
		want, err := hotp.GenerateCodeCustom(s, uint64(candidate), totpOpts) // #nosec G115 -- steps are positive
		if err != nil {
			return 0, false
		}
		if subtle.ConstantTimeCompare([]byte(want), []byte(code)) == 1 && candidate > after {
			step, ok = candidate, true
		}
	}
	return step, ok
}

// consumeTOTPStep records step as the last accepted time step of the credential, if it is newer than the one
// recorded; it reports whether it was, and records the day as the credential's last use. Of two requests with the
// same code only one gets true.
func consumeTOTPStep(app core.App, credential *core.Record, step int64) (bool, error) {
	t := dbTime(now())
	res, err := app.DB().Update(store.Credentials, dbx.Params{"totp_last_step": step, store.FieldUpdated: t,
		"last_used_at": dbTime(day(now()))},
		dbx.And(dbx.HashExp{"id": credential.Id}, dbx.NewExp("totp_last_step < {:step}", dbx.Params{"step": step}))).
		Execute()
	if err != nil {
		return false, err
	}
	n, err := res.RowsAffected()
	return n == 1, err
}
